=== FILE: apb_regs.v ===
`timescale 1ns/1ps
`default_nettype none

// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements interface_spec.md and microarchitecture.md (block apb_regs).
//  - Zero wait states: pready is tied high.
//  - access = psel && penable is the one cycle in which writes commit and
//    the response is sampled.
//  - Mapped addresses: word aligned and in 0x0..0xC. Everything else in the
//    slot is unmapped and answers pslverr in the access phase.
//  - prdata and pslverr are zero outside the access phase.
module apb_regs #(
    parameter ADDR_WIDTH = 8,
    parameter DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

    localparam STRB_WIDTH = DATA_WIDTH / 8;

    // ------------------------------------------------------------------
    // Decode
    // ------------------------------------------------------------------
    wire                  access;
    wire                  mapped;
    wire [1:0]            idx;
    wire                  wr_en;
    wire                  rd_en;
    wire [DATA_WIDTH-1:0] wmask;

    assign access = psel & penable;
    assign mapped = (paddr[1:0] == 2'b00) &&
                    (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
    assign idx    = paddr[3:2];
    assign wr_en  = access & pwrite & mapped;
    assign rd_en  = access & ~pwrite & mapped;

    // Byte-lane write mask from pstrb: lane n is bits 8n+7:8n.
    genvar g;
    generate
        for (g = 0; g < STRB_WIDTH; g = g + 1) begin : g_mask
            assign wmask[8*g +: 8] = {8{pstrb[g]}};
        end
    endgenerate

    // ------------------------------------------------------------------
    // Register file: four separate flops
    // ------------------------------------------------------------------
    reg  [DATA_WIDTH-1:0] reg0;
    reg  [DATA_WIDTH-1:0] reg1;
    reg  [DATA_WIDTH-1:0] reg2;
    reg  [DATA_WIDTH-1:0] reg3;

    wire [DATA_WIDTH-1:0] reg0_nxt;
    wire [DATA_WIDTH-1:0] reg1_nxt;
    wire [DATA_WIDTH-1:0] reg2_nxt;
    wire [DATA_WIDTH-1:0] reg3_nxt;

    wire                  wr0;
    wire                  wr1;
    wire                  wr2;
    wire                  wr3;

    // merge(old, data, strb): strobed bytes from pwdata, others kept.
    assign reg0_nxt = (reg0 & ~wmask) | (pwdata & wmask);
    assign reg1_nxt = (reg1 & ~wmask) | (pwdata & wmask);
    assign reg2_nxt = (reg2 & ~wmask) | (pwdata & wmask);
    assign reg3_nxt = (reg3 & ~wmask) | (pwdata & wmask);

    assign wr0 = wr_en & (idx == 2'd0);
    assign wr1 = wr_en & (idx == 2'd1);
    assign wr2 = wr_en & (idx == 2'd2);
    assign wr3 = wr_en & (idx == 2'd3);

    // Synchronous, active-low reset; load enable per register.
    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else begin
            if (wr0) reg0 <= reg0_nxt;
            if (wr1) reg1 <= reg1_nxt;
            if (wr2) reg2 <= reg2_nxt;
            if (wr3) reg3 <= reg3_nxt;
        end
    end

    // ------------------------------------------------------------------
    // Read data: combinational 4:1 mux, zero unless a mapped read access
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] rd_mux;

    always @* begin
        case (idx)
            2'd0:    rd_mux = reg0;
            2'd1:    rd_mux = reg1;
            2'd2:    rd_mux = reg2;
            2'd3:    rd_mux = reg3;
            default: rd_mux = {DATA_WIDTH{1'b0}};
        endcase
    end

    assign prdata  = rd_en ? rd_mux : {DATA_WIDTH{1'b0}};
    assign pready  = 1'b1;
    assign pslverr = access & ~mapped;

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent properties. The decode and byte model below are written
    // independently of the design's decode and merge.
    // ------------------------------------------------------------------
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge pclk) f_past_valid <= 1'b1;

    wire                    f_access = psel && penable;
    wire                    f_mapped = (paddr < 16) && (paddr[1:0] == 2'b00);
    wire [4*DATA_WIDTH-1:0] f_regs   = {reg3, reg2, reg1, reg0};

    // Manager assumptions (interface_spec sections 4 and 6).
    always @(*) begin
        if (!f_past_valid) assume(!presetn);
        if (!presetn)      assume(!psel);
        if (penable)       assume(psel);
    end

    always @(posedge pclk) begin
        if (f_past_valid) begin
            // Setup is followed by access with a stable request.
            if ($past(presetn) && $past(psel) && !$past(penable)) begin
                assume(psel && penable);
                assume(paddr  == $past(paddr));
                assume(pwrite == $past(pwrite));
                assume(pwdata == $past(pwdata));
                assume(pstrb  == $past(pstrb));
            end
            // penable only in the cycle after a setup phase.
            if (penable) assume($past(psel) && !$past(penable));
        end
    end

    // Response rules.
    always @(*) begin
        assert(pready);
        if (!f_access) begin
            assert(prdata == {DATA_WIDTH{1'b0}});
            assert(!pslverr);
        end else begin
            assert(pslverr == !f_mapped);
            if (f_mapped && !pwrite)
                assert(prdata == f_regs[paddr[3:2]*DATA_WIDTH +: DATA_WIDTH]);
            else
                assert(prdata == {DATA_WIDTH{1'b0}});
        end
    end

    // Register rules: zero after reset; each byte changes only in a mapped
    // write access to its register with its strobe set, to the written byte.
    genvar f_b;
    generate
        for (f_b = 0; f_b < 4*STRB_WIDTH; f_b = f_b + 1) begin : g_f_byte
            always @(posedge pclk) begin
                if (f_past_valid) begin
                    if (!$past(presetn))
                        assert(f_regs[8*f_b +: 8] == 8'h00);
                    else if ($past(f_access && pwrite && f_mapped) &&
                             ($past(paddr[3:2]) == (f_b / STRB_WIDTH)) &&
                             $past(pstrb[f_b % STRB_WIDTH]))
                        assert(f_regs[8*f_b +: 8] ==
                               $past(pwdata[8*(f_b % STRB_WIDTH) +: 8]));
                    else
                        assert(f_regs[8*f_b +: 8] == $past(f_regs[8*f_b +: 8]));
                end
            end
        end
    endgenerate

    // Non-vacuity covers.
    always @(*) begin
        cover(f_access && pwrite && f_mapped && (pstrb != 0));
        cover(f_access && !pwrite && f_mapped && (prdata != 0));
        cover(f_access && !f_mapped && pslverr);
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_regs_tb.v ===
`timescale 1ns/1ps
`default_nettype none

`define CHECK(cond, msg) \
    begin \
        if (cond) begin \
            passed = passed + 1; \
        end else begin \
            failed = failed + 1; \
            $error msg; \
        end \
    end

// apb_regs_tb: directed, self-checking testbench for apb_regs.
// Inputs are driven after the falling edge and outputs are sampled 1 ns
// later, well before the next rising edge.
module apb_regs_tb;

    reg         pclk;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;

    integer        passed;
    integer        failed;
    integer        got_nonce;
    reg [8*64-1:0] nonce;

    // Reference model of the four registers.
    reg [31:0] model [0:3];

    reg [2:0] r;
    reg [4:0] s;
    reg [4:0] u;

    apb_regs #(
        .ADDR_WIDTH(8),
        .DATA_WIDTH(32)
    ) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // ------------------------------------------------------------------
    // Reference functions (independent of the RTL)
    // ------------------------------------------------------------------
    function tb_mapped;
        input [7:0] a;
        begin
            tb_mapped = (a[1:0] == 2'b00) && (a < 8'h10);
        end
    endfunction

    function [31:0] tb_merge;
        input [31:0] old_v;
        input [31:0] new_v;
        input [3:0]  strb;
        begin
            tb_merge = old_v;
            if (strb[0]) tb_merge[7:0]   = new_v[7:0];
            if (strb[1]) tb_merge[15:8]  = new_v[15:8];
            if (strb[2]) tb_merge[23:16] = new_v[23:16];
            if (strb[3]) tb_merge[31:24] = new_v[31:24];
        end
    endfunction

    function [31:0] tb_pattern;
        input [1:0] ri;
        begin
            case (ri)
                2'd0:    tb_pattern = 32'h1234_5678;
                2'd1:    tb_pattern = 32'h9ABC_DEF0;
                2'd2:    tb_pattern = 32'hCAFE_F00D;
                2'd3:    tb_pattern = 32'h0BAD_C0DE;
                default: tb_pattern = 32'h0000_0000;
            endcase
        end
    endfunction

    // Unmapped addresses: misaligned and out of range.
    function [7:0] tb_unmapped;
        input [4:0] ui;
        begin
            case (ui)
                5'd0:    tb_unmapped = 8'h01;
                5'd1:    tb_unmapped = 8'h02;
                5'd2:    tb_unmapped = 8'h03;
                5'd3:    tb_unmapped = 8'h05;
                5'd4:    tb_unmapped = 8'h06;
                5'd5:    tb_unmapped = 8'h07;
                5'd6:    tb_unmapped = 8'h09;
                5'd7:    tb_unmapped = 8'h0D;
                5'd8:    tb_unmapped = 8'h0F;
                5'd9:    tb_unmapped = 8'h10;
                5'd10:   tb_unmapped = 8'h14;
                5'd11:   tb_unmapped = 8'h18;
                5'd12:   tb_unmapped = 8'h1C;
                5'd13:   tb_unmapped = 8'h20;
                5'd14:   tb_unmapped = 8'h80;
                5'd15:   tb_unmapped = 8'hFC;
                default: tb_unmapped = 8'hFF;
            endcase
        end
    endfunction

    // ------------------------------------------------------------------
    // Bus tasks
    // ------------------------------------------------------------------

    // One APB transfer: setup cycle, then one access cycle. Returns just
    // after the rising edge that ends the access phase, so a following
    // call starts a back-to-back setup phase.
    task apb_xfer;
        input        wr;
        input [7:0]  addr;
        input [31:0] wdata;
        input [3:0]  strb;
        input [31:0] exp_rdata;
        input        exp_err;
        begin
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = wr;
            paddr   = addr;
            pwdata  = wdata;
            pstrb   = strb;
            #1;
            `CHECK(prdata === 32'h0000_0000, ("setup @%h: prdata %h, expected zero", addr, prdata))
            `CHECK(pslverr === 1'b0, ("setup @%h: pslverr high outside access phase", addr))
            @(negedge pclk);
            penable = 1'b1;
            #1;
            `CHECK(pready === 1'b1, ("access @%h: pready low, expected zero wait states", addr))
            `CHECK(pslverr === exp_err, ("access @%h: pslverr %b, expected %b", addr, pslverr, exp_err))
            `CHECK(prdata === exp_rdata, ("access @%h: prdata %h, expected %h", addr, prdata, exp_rdata))
            @(posedge pclk);
        end
    endtask

    task apb_write;
        input [7:0]  addr;
        input [31:0] wdata;
        input [3:0]  strb;
        begin
            if (tb_mapped(addr)) begin
                apb_xfer(1'b1, addr, wdata, strb, 32'h0000_0000, 1'b0);
                model[addr[3:2]] = tb_merge(model[addr[3:2]], wdata, strb);
            end else begin
                apb_xfer(1'b1, addr, wdata, strb, 32'h0000_0000, 1'b1);
            end
        end
    endtask

    // Reads drive non-zero pwdata to show a read never writes.
    task apb_read;
        input [7:0] addr;
        begin
            if (tb_mapped(addr))
                apb_xfer(1'b0, addr, 32'hDEAD_BEEF, 4'h0, model[addr[3:2]], 1'b0);
            else
                apb_xfer(1'b0, addr, 32'hDEAD_BEEF, 4'h0, 32'h0000_0000, 1'b1);
        end
    endtask

    task read_all;
        reg [2:0] rr;
        begin
            for (rr = 3'd0; rr < 3'd4; rr = rr + 3'd1)
                apb_read({3'b000, rr, 2'b00});
        end
    endtask

    task idle;
        input integer n;
        integer k;
        begin
            for (k = 0; k < n; k = k + 1) begin
                @(negedge pclk);
                psel    = 1'b0;
                penable = 1'b0;
                pwrite  = 1'b0;
                paddr   = 8'h00;
                pwdata  = 32'h0000_0000;
                pstrb   = 4'h0;
                #1;
                `CHECK(prdata === 32'h0000_0000, ("idle: prdata %h, expected zero", prdata))
                `CHECK(pslverr === 1'b0, ("idle: pslverr high outside access phase"))
            end
        end
    endtask

    task do_reset;
        integer k;
        begin
            @(negedge pclk);
            presetn = 1'b0;
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = 8'h00;
            pwdata  = 32'h0000_0000;
            pstrb   = 4'h0;
            for (k = 0; k < 3; k = k + 1) begin
                #1;
                `CHECK(pready === 1'b1, ("reset: pready low"))
                `CHECK(prdata === 32'h0000_0000, ("reset: prdata %h, expected zero", prdata))
                `CHECK(pslverr === 1'b0, ("reset: pslverr high"))
                @(negedge pclk);
            end
            presetn  = 1'b1;
            model[0] = 32'h0000_0000;
            model[1] = 32'h0000_0000;
            model[2] = 32'h0000_0000;
            model[3] = 32'h0000_0000;
        end
    endtask

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        passed   = 0;
        failed   = 0;
        presetn  = 1'b0;
        psel     = 1'b0;
        penable  = 1'b0;
        pwrite   = 1'b0;
        paddr    = 8'h00;
        pwdata   = 32'h0000_0000;
        pstrb    = 4'h0;
        model[0] = 32'h0000_0000;
        model[1] = 32'h0000_0000;
        model[2] = 32'h0000_0000;
        model[3] = 32'h0000_0000;
        got_nonce = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (got_nonce == 0) nonce = {(8*64){1'b0}};

        // 1. Reset values.
        do_reset;
        read_all;

        // 2. Full-word write of every register (back to back), idle gap,
        //    then read back (back to back).
        for (r = 3'd0; r < 3'd4; r = r + 3'd1)
            apb_write({3'b000, r, 2'b00}, tb_pattern(r[1:0]), 4'hF);
        idle(2);
        read_all;

        // 3. Back-to-back transfers with mixed directions, including a read
        //    straight after a write to the same register.
        apb_write(8'h04, 32'h0F1E_2D3C, 4'hF);
        apb_read(8'h04);
        apb_write(8'h0C, 32'h8796_A5B4, 4'hF);
        apb_read(8'h00);
        apb_read(8'h0C);
        idle(1);

        // 4. Every pstrb pattern on REG2, including none.
        apb_write(8'h08, 32'h0000_0000, 4'hF);
        for (s = 5'd0; s < 5'd16; s = s + 5'd1) begin
            apb_write(8'h08, {8{s[3:0]}} ^ 32'h5AC3_96E1, s[3:0]);
            apb_read(8'h08);
            if (s[1:0] == 2'b11) idle(1);
        end

        // Single-byte and mixed partial writes on REG0 and REG3.
        apb_write(8'h00, 32'h1111_1111, 4'h1);
        apb_write(8'h00, 32'h2222_2222, 4'h2);
        apb_write(8'h00, 32'h3333_3333, 4'h4);
        apb_write(8'h00, 32'h4444_4444, 4'h8);
        apb_read(8'h00);
        apb_write(8'h0C, 32'hA5A5_A5A5, 4'h6);
        apb_write(8'h0C, 32'h5A5A_5A5A, 4'h9);
        idle(3);
        read_all;

        // 5. Zero-strobe writes to every register change nothing.
        for (r = 3'd0; r < 3'd4; r = r + 3'd1)
            apb_write({3'b000, r, 2'b00}, 32'hFFFF_FFFF, 4'h0);
        read_all;

        // 6. Unmapped addresses: writes error and change nothing (no
        //    aliasing onto a register), reads error and return zero.
        for (u = 5'd0; u < 5'd17; u = u + 5'd1)
            apb_write(tb_unmapped(u), 32'hFFFF_FFFF, 4'hF);
        idle(3);
        read_all;
        for (u = 5'd0; u < 5'd17; u = u + 5'd1)
            apb_read(tb_unmapped(u));
        idle(1);
        read_all;

        // 7. Reset again: every register returns to zero.
        do_reset;
        read_all;

        // 8. The block works after the second reset.
        apb_write(8'h0C, 32'hC0FF_EE00, 4'hF);
        apb_read(8'h0C);
        apb_read(8'h08);
        idle(1);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`undef CHECK
`default_nettype wire
=== END FILE ===
